8	import {resolve, basename} from 'node:path';
9	import logger, {PerfLogger} from '@docusaurus/logger';
10	import {getGitAllRepoRoots, getGitRepositoryFilesInfo} from './gitUtils';
11	import type {GitFileInfo, GitFileInfoMap} from './gitUtils';
12	import type {VcsConfig} from '@docusaurus/types';
13	
14	// The Map keys should be absolute file paths, not relative Git paths
15	function resolveFileInfoMapPaths(
16	  repoRoot: string,
17	  filesInfo: GitFileInfoMap,
18	): GitFileInfoMap {
19	  function transformMapEntry(
20	    entry: [string, GitFileInfo],
21	  ): [string, GitFileInfo] {
22	    // We just resolve the Git paths that are relative to the repo root
23	    return [resolve(repoRoot, entry[0]), entry[1]];
24	  }
25	
26	  return new Map(Array.from(filesInfo.entries()).map(transformMapEntry));
27	}
28	
29	function mergeFileMaps(fileMaps: GitFileInfoMap[]): GitFileInfoMap {
30	  return new Map(fileMaps.flatMap((m) => [...m]));
31	}
32	
33	async function loadAllGitFilesInfoMap(cwd: string): Promise<GitFileInfoMap> {
34	  const roots = await PerfLogger.async('Reading Git root dirs', () =>
35	    getGitAllRepoRoots(cwd),
36	  );
37	
38	  const allMaps: GitFileInfoMap[] = await Promise.all(
39	    roots.map(async (root) => {
40	      const map = await PerfLogger.async(
41	        `Reading Git history for repo ${logger.path(basename(root))}`,
42	        () => getGitRepositoryFilesInfo(root),
43	      );
44	      return resolveFileInfoMapPaths(root, map);
45	    }),
46	  );
47	
48	  return mergeFileMaps(allMaps);
49	}
50	
51	function createGitVcsConfig(): VcsConfig {
52	  let filesMapPromise: Promise<GitFileInfoMap> | null = null;
53	
54	  async function getGitFileInfo(filePath: string): Promise<GitFileInfo | null> {
55	    const filesMap = await filesMapPromise;
56	    return filesMap?.get(filePath) ?? null;
57	  }
58	
59	  return {
60	    initialize: ({siteDir}) => {
61	      if (filesMapPromise) {
62	        // We only initialize this VCS once!
63	        // For i18n sites, this permits reading ahead of time for all locales
64	        // so that it only slows down the first locale
65	        // I assume this logic is fine, but we'll see if it causes trouble
66	
67	        // Note: we could also only call "initialize()" once from the outside,
68	        // But maybe it could be useful for custom VCS implementations to be
69	        // able to initialize once per locale?
70	        PerfLogger.log(
71	          'Git Eager VCS strategy already initialized, skipping re-initialization',
72	        );
73	        return;
74	      }
75	
76	      filesMapPromise = PerfLogger.async('Git Eager VCS init', () =>
77	        loadAllGitFilesInfoMap(siteDir),
78	      );
79	      filesMapPromise.catch((error) => {
80	        console.error(
81	          'Failed to initialize the Docusaurus Git Eager VCS strategy',
82	          error,
83	        );
84	      });
85	    },
86	
87	    getFileCreationInfo: async (filePath: string) => {
88	      const fileInfo = await getGitFileInfo(filePath);
89	      return fileInfo?.creation ?? null;
90	    },
91	
92	    getFileLastUpdateInfo: async (filePath: string) => {
93	      const fileInfo = await getGitFileInfo(filePath);
94	      return fileInfo?.lastUpdate ?? null;
95	    },
96	  };
97	}
98	
99	export const VscGitEager: VcsConfig = createGitVcsConfig();
