8	import path from 'path';
9	import fs from 'fs-extra';
10	import os from 'os';
11	import _ from 'lodash';
12	import execa from 'execa';
13	import PQueue from 'p-queue';
14	import logger from '@docusaurus/logger';
15	
16	// Quite high/conservative concurrency value (it was previously "Infinity")
17	// See https://github.com/facebook/docusaurus/pull/10915
18	const DefaultGitCommandConcurrency =
19	  // TODO Docusaurus v4: bump node, availableParallelism() now always exists
20	  (typeof os.availableParallelism === 'function'
21	    ? os.availableParallelism()
22	    : os.cpus().length) * 4;
23	
24	const GitCommandConcurrencyEnv = process.env.DOCUSAURUS_GIT_COMMAND_CONCURRENCY
25	  ? parseInt(process.env.DOCUSAURUS_GIT_COMMAND_CONCURRENCY, 10)
26	  : undefined;
27	
28	const GitCommandConcurrency =
29	  GitCommandConcurrencyEnv && GitCommandConcurrencyEnv > 0
30	    ? GitCommandConcurrencyEnv
31	    : DefaultGitCommandConcurrency;
32	
33	// We use a queue to avoid running too many concurrent Git commands at once
34	// See https://github.com/facebook/docusaurus/issues/10348
35	const GitCommandQueue = new PQueue({
36	  concurrency: GitCommandConcurrency,
37	});
38	
39	const realHasGitFn = () => {
40	  try {
41	    return execa.sync('git', ['--version']).exitCode === 0;
42	  } catch (error) {
43	    return false;
44	  }
45	};
46	
47	// The hasGit call is synchronous IO so we memoize it
48	// The user won't install Git in the middle of a build anyway...
49	const hasGit =
50	  process.env.NODE_ENV === 'test' ? realHasGitFn : _.memoize(realHasGitFn);
