62	/**
63	 * Fetches the git history of a file and returns a relevant commit date.
64	 * It gets the commit date instead of author date so that amended commits
65	 * can have their dates updated.
66	 *
67	 * @throws {@link GitNotFoundError} If git is not found in `PATH`.
68	 * @throws {@link FileNotTrackedError} If the current file is not tracked by git.
69	 * @throws Also throws when `git log` exited with non-zero, or when it outputs
70	 * unexpected text.
71	 */
72	export async function getFileCommitDate(
73	  /** Absolute path to the file. */
74	  file: string,
75	  args: {
76	    /**
77	     * `"oldest"` is the commit that added the file, following renames;
78	     * `"newest"` is the last commit that edited the file.
79	     */
80	    age?: 'oldest' | 'newest';
81	    /** Use `includeAuthor: true` to get the author information as well. */
82	    includeAuthor?: false;
83	  },
84	): Promise<{
85	  /** Relevant commit date. */
86	  date: Date; // TODO duplicate data, not really useful?
87	  /** Timestamp returned from git, converted to **milliseconds**. */
88	  timestamp: number;
89	}>;
90	/**
91	 * Fetches the git history of a file and returns a relevant commit date.
92	 * It gets the commit date instead of author date so that amended commits
93	 * can have their dates updated.
94	 *
95	 * @throws {@link GitNotFoundError} If git is not found in `PATH`.
96	 * @throws {@link FileNotTrackedError} If the current file is not tracked by git.
97	 * @throws Also throws when `git log` exited with non-zero, or when it outputs
98	 * unexpected text.
99	 */
100	export async function getFileCommitDate(
101	  /** Absolute path to the file. */
102	  file: string,
103	  args: {
104	    /**
105	     * `"oldest"` is the commit that added the file, following renames;
106	     * `"newest"` is the last commit that edited the file.
107	     */
108	    age?: 'oldest' | 'newest';
109	    includeAuthor: true;
110	  },
111	): Promise<{
112	  /** Relevant commit date. */
113	  date: Date;
114	  /** Timestamp returned from git, converted to **milliseconds**. */
115	  timestamp: number;
116	  /** The author's name, as returned from git. */
117	  author: string;
118	}>;
119	
120	export async function getFileCommitDate(
121	  file: string,
122	  {
123	    age = 'oldest',
124	    includeAuthor = false,
125	  }: {
126	    age?: 'oldest' | 'newest';
127	    includeAuthor?: boolean;
128	  },
129	): Promise<{
130	  date: Date;
131	  timestamp: number;
132	  author?: string;
133	}> {
134	  if (!hasGit()) {
135	    throw new GitNotFoundError(
136	      `Failed to retrieve git history for "${file}" because git is not installed.`,
137	    );
138	  }
139	
140	  if (!(await fs.pathExists(file))) {
141	    throw new Error(
142	      `Failed to retrieve git history for "${file}" because the file does not exist.`,
143	    );
144	  }
145	
146	  // We add a "RESULT:" prefix to make parsing easier
147	  // See why: https://github.com/facebook/docusaurus/pull/10022
148	  const resultFormat = includeAuthor ? 'RESULT:%ct,%an' : 'RESULT:%ct';
149	
150	  const args = [
151	    `--format=${resultFormat}`,
152	    '--max-count=1',
153	    age === 'oldest' ? '--follow --diff-filter=A' : undefined,
154	  ]
155	    .filter(Boolean)
156	    .join(' ');
157	
158	  // Do not include GPG signature in the log output
159	  // See https://github.com/facebook/docusaurus/pull/10022
160	  const command = `git -c log.showSignature=false log ${args} -- "${path.basename(
161	    file,
162	  )}"`;
163	
164	  const result = (await GitCommandQueue.add(() => {
165	    return execa(command, {
166	      cwd: path.dirname(file),
167	      shell: true,
168	    });
169	  }))!;
170	
171	  if (result.exitCode !== 0) {
172	    throw new Error(
173	      `Failed to retrieve the git history for file "${file}" with exit code ${result.exitCode}: ${result.stderr}`,
174	    );
175	  }
176	
177	  // We only parse the output line starting with our "RESULT:" prefix
178	  // See why https://github.com/facebook/docusaurus/pull/10022
179	  const regex = includeAuthor
180	    ? /(?:^|\n)RESULT:(?<timestamp>\d+),(?<author>.+)(?:$|\n)/
181	    : /(?:^|\n)RESULT:(?<timestamp>\d+)(?:$|\n)/;
182	
183	  const output = result.stdout.trim();
184	
185	  if (!output) {
186	    throw new FileNotTrackedError(
187	      `Failed to retrieve the git history for file "${file}" because the file is not tracked by git.`,
188	    );
189	  }
190	
191	  const match = output.match(regex);
192	
193	  if (!match) {
194	    throw new Error(
195	      `Failed to retrieve the git history for file "${file}" with unexpected output: ${output}`,
196	    );
197	  }
198	
199	  const timestampInSeconds = Number(match.groups!.timestamp);
200	  const timestamp = timestampInSeconds * 1_000;
201	  const date = new Date(timestamp);
202	
203	  if (includeAuthor) {
204	    return {date, timestamp, author: match.groups!.author!};
205	  }
206	  return {date, timestamp};
207	}
