  async function getGitFileInfo(
    filePath: string,
  ): Promise<GitFileInfo | null> {
    try {
      const filesMap = await filesMapPromise;
      return filesMap?.get(filePath) ?? null;
    } catch (error) {
      if (error instanceof NotInGitWorktreeError) {
        throw new Error(
